1	import "server-only";
2	import os from "node:os";
3	import path from "node:path";
4	import fs from "node:fs";
5	import { notify } from "./notify";
6	
7	// S95: claude / codex CLI 的授权健康探测 + 到期预警。
8	//
9	// 动机是 S90→S93 那次故障：prod spawn 的 claude 全部认证失败，**挂了 6 天没人
10	// 知道**——错误只出现在没人看的会话里，凭证的时效没有任何地方可见。这层做两件事：
11	//   T0 `getAuthHealth()`：给 /api/auth-health 和设置页一个只读快照；
12	//   T1 `checkAuthAlerts()`：scheduler 每小时调一次，硬条件命中就走 notify 推送。
13	//
14	// 事实依据（S93 实测 + claude-code-guide 查证，都记在 sessions.md S93/S95）：
15	//  · `claude auth status --json` 是官方状态出口（2.1.207 实测），但**不含过期时间**；
16	//  · 过期时间只能读 `~/.claude/.credentials.json`——**非公开 API**，所以解析失败
17	//    一律降级成「未知」，绝不让整个探测报错；
18	//  · macOS Keychain 里的 `Claude Code-credentials` 是第二份存储。launchd 上下文的
19	//    claude 读它、终端读文件，副本停更（refresh token 被文件侧轮换作废）就是 S93
20	//    的根因 —— 所以这里带一个「分叉哨兵」；
21	//  · codex 走 `codex login status`；trellis 的 codex 运行通常经 config.toml 的
22	//    第三方 provider（静态 key），ChatGPT 登录态只影响官方模式 → codex 只展示不告警。
23	
24	export type CliAuthHealth = {
25	  installed: boolean;
26	  /** null = 探测失败（区别于明确的未登录） */
27	  loggedIn: boolean | null;
28	  method: string | null;
29	  subscription: string | null;
30	  account: string | null;
31	  /** access token 过期时刻（ms）。null = 未知（文件缺失/解析失败） */
32	  accessExpiresAt: number | null;
33	  /** refresh token 过期时刻（ms）——这个过了才是真死（CLI 自己会用 refresh 续 access） */
34	  refreshExpiresAt: number | null;
35	  /** 凭证最后一次落盘（claude=credentials.json mtime；codex=auth.json 的 last_refresh） */
36	  credentialUpdatedAt: number | null;
37	  warnings: string[];
38	  errors: string[];
39	};
40	
41	export type AuthHealth = {
42	  claude: CliAuthHealth;
43	  codex: CliAuthHealth;
44	  checkedAt: number;
45	};
46	
47	const PROBE_TIMEOUT_MS = 10_000;
48	/** refresh token 剩余不足这个数就预警——过期后修复要人工走登录，留 3 天余量。 */
49	const REFRESH_WARN_MS = 72 * 3600_000;
50	/** keychain 副本落后文件超过这个数判分叉（正常同步不会差出两天）。 */
51	const SPLIT_BRAIN_LAG_MS = 48 * 3600_000;
52	
53	async function runCmd(
54	  argv: string[],
55	): Promise<{ code: number; stdout: string; stderr: string } | null> {
56	  try {
57	    // cwd 固定 homedir：S88 实测 cwd 不存在时 spawn 的 ENOENT 是异步
58	    // uncaughtException，try/catch 兜不住 —— 别给它机会。
59	    const proc = Bun.spawn(argv, {
60	      cwd: os.homedir(),
61	      stdout: "pipe",
62	      stderr: "pipe",
63	    });
64	    const timer = setTimeout(() => proc.kill(), PROBE_TIMEOUT_MS);
65	    try {
66	      const [stdout, stderr] = await Promise.all([
67	        new Response(proc.stdout).text(),
68	        new Response(proc.stderr).text(),
69	      ]);
70	      await proc.exited;
71	      return { code: proc.exitCode ?? -1, stdout, stderr };
72	    } finally {
73	      clearTimeout(timer);
74	    }
75	  } catch {
76	    return null; // 二进制不存在（PATH 里没有）等 spawn 期失败
77	  }
78	}
79	
80	// ---------------------------------------------------------------------------
81	// claude
82	// ---------------------------------------------------------------------------
83	
84	function readClaudeCredentialFile(): {
85	  accessExpiresAt: number | null;
86	  refreshExpiresAt: number | null;
87	  mtime: number | null;
88	} {
89	  const p = path.join(os.homedir(), ".claude", ".credentials.json");
90	  try {
91	    const mtime = fs.statSync(p).mtimeMs;
92	    const o = JSON.parse(fs.readFileSync(p, "utf8"))?.claudeAiOauth;
93	    return {
94	      accessExpiresAt: typeof o?.expiresAt === "number" ? o.expiresAt : null,
95	      refreshExpiresAt:
96	        typeof o?.refreshTokenExpiresAt === "number" ? o.refreshTokenExpiresAt : null,
97	      mtime,
98	    };
99	  } catch {
100	    return { accessExpiresAt: null, refreshExpiresAt: null, mtime: null };
101	  }
102	}
103	
104	/** macOS Keychain 里第二份凭证的最后写入时刻；条目不存在 / 非 macOS → null。 */
105	async function keychainItemMtime(): Promise<number | null> {
106	  if (process.platform !== "darwin") return null;
107	  const r = await runCmd([
108	    "/usr/bin/security",
109	    "find-generic-password",
110	    "-s",
111	    "Claude Code-credentials",
112	  ]);
113	  if (!r || r.code !== 0) return null;
114	  // 形如 "mdat"<timedate>=0x… "20260726020027Z\000"
115	  const m = /"mdat"<timedate>=[^"]*"(\d{14})Z/.exec(r.stdout + r.stderr);
116	  if (!m) return 0; // 条目在但读不出时间：仍要报「存在第二份存储」
117	  const [, t] = m;
118	  return Date.UTC(
119	    Number(t.slice(0, 4)),
120	    Number(t.slice(4, 6)) - 1,
121	    Number(t.slice(6, 8)),
122	    Number(t.slice(8, 10)),
123	    Number(t.slice(10, 12)),
124	    Number(t.slice(12, 14)),
125	  );
126	}
127	
128	async function probeClaude(): Promise<CliAuthHealth> {
129	  const h: CliAuthHealth = {
130	    installed: false,
131	    loggedIn: null,
132	    method: null,
133	    subscription: null,
134	    account: null,
135	    accessExpiresAt: null,
136	    refreshExpiresAt: null,
137	    credentialUpdatedAt: null,
138	    warnings: [],
139	    errors: [],
140	  };
141	
142	  const r = await runCmd(["claude", "auth", "status", "--json"]);
143	  if (!r) {
144	    // S91 就点过名的隐患：plist 的 PATH 写死 nvm 版本目录，node 一升级 claude
145	    // 就从 prod 的 PATH 消失 —— 这里让它第一次有了可见的症状。
146	    h.errors.push("PATH 里找不到 claude —— prod spawn 会全部失败（nvm 升级后 plist PATH 失效是已知诱因）");
147	    return h;
148	  }
149	  h.installed = true;
150	  try {
151	    const s = JSON.parse(r.stdout);
152	    h.loggedIn = Boolean(s.loggedIn);
153	    h.method = typeof s.authMethod === "string" ? s.authMethod : null;
154	    h.subscription = typeof s.subscriptionType === "string" ? s.subscriptionType : null;
155	    h.account = typeof s.email === "string" ? s.email : null;
156	  } catch {
157	    h.loggedIn = r.code === 0 ? null : false;
158	    h.errors.push(`claude auth status 输出无法解析（exit ${r.code}）`);
159	  }
160	  // authMethod 语义翻译（S96，2026-08-05 逐来源实测）：`oauth_token` = 登录态来自
