        // 避免只剩 generic "codex error"。
        const stderrSink = { text: "" };
        for await (const raw of streamLines("codex", args, {
            cwd: opts.cwd ?? opts.workspace ?? undefined,
            env: spawnEnv,
            signal: opts.signal,
            stderrSink,
