                // (带输出/错误)。此前只在 completed 发一条无 id 的 ToolCall——上游按 id
                // 去重会把整轮工具吞到只剩一条,且永远 running。
                const item = obj.item;
                const id = item.id ?? `codex-tool-${anonToolSeq++}`;
