/**
 * modelhub-proxy —— 轻量路径+鉴权适配器。
 * 把标准 OpenAI /v1/chat/completions 请求转发到模型站的 /crawl 端点，
 * 同时把 Authorization header 翻译成 ak query param。
 * 不做任何协议转换——模型站本身就是 OpenAI 格式。
 */
const http = require("node:http");
const https = require("node:https");

const MODELHUB_URL =
  "https://aidp.bytedance.net/api/modelhub/online/v2/crawl?ak=fMKe7eK4KINDrfDCvtuiLisHoMpvbpMf_GPT_AK";
const PORT = parseInt(process.env.PORT || "3456", 10);

const server = http.createServer((req, res) => {
  // CORS preflight
  if (req.method === "OPTIONS") {
    res.writeHead(204, {
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Methods": "POST, OPTIONS",
      "Access-Control-Allow-Headers": "Content-Type, Authorization",
    });
    res.end();
    return;
  }

  // 健康检查
  if (req.url.split("?")[0] === "/health" || req.url.split("?")[0] === "/") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ ok: true, service: "modelhub-proxy" }));
    return;
  }

  // 只接受 /v1/chat/completions——纯透传到模型站
  if (req.method !== "POST" || req.url.split("?")[0] !== "/v1/chat/completions") {
    res.writeHead(404, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ error: { type: "not_found", message: "Not found" } }));
    return;
  }

  let body = "";
  req.on("data", (chunk) => { body += chunk.toString("utf-8"); });
  req.on("end", () => {
    let openaiReq;
    try {
      openaiReq = JSON.parse(body);
    } catch {
      res.writeHead(400, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ error: { type: "bad_request", message: "Invalid JSON" } }));
      return;
    }

    const url = new URL(MODELHUB_URL);
    const proxyReq = https.request(
      {
        hostname: url.hostname,
        port: 443,
        path: url.pathname + url.search,
        method: "POST",
        headers: { "Content-Type": "application/json" },
        timeout: 120000,
      },
      (proxyRes) => {
        // 直接透传状态码、headers、body（含 streaming SSE）
        res.writeHead(proxyRes.statusCode || 502, {
          "Content-Type": proxyRes.headers["content-type"] || "application/json",
          "Access-Control-Allow-Origin": "*",
        });
        proxyRes.pipe(res);
      },
    );

    proxyReq.on("error", (e) => {
      res.writeHead(502, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ error: { type: "proxy_error", message: e.message } }));
    });

    proxyReq.write(JSON.stringify(openaiReq));
    proxyReq.end();
  });
});

server.listen(PORT, "127.0.0.1", () => {
  console.log("modelhub-proxy listening on http://127.0.0.1:" + PORT);
});

